// Public v1.2.0 foundation; generated by scripts/catalog.mjs.
export const FOUNDATION_CSS = "/* Powermove — design tokens. Default theme is light; dark is the alternate.\n\n   The palette is small on purpose: three surfaces, one text color that every\n   hairline, wash, and muted tone is an alpha step of, one accent, three\n   semantic status hues. Everything else in the app derives from these. */\n:root{color-scheme:light}\n:root[data-theme=\"dark\"]{color-scheme:dark}\n:root{\n  /* ── ink: the one color everything neutral is derived from ── */\n  --ink-rgb:20 22 28;\n  --paper-rgb:255 255 255;\n\n  /* ── surfaces (canvas → surface → elevated) ── */\n  --bg-window:#EEEEF1;   /* canvas */\n  --bg-rail:#F3F3F6;\n  --bg-panel:#FDFDFE;    /* surface */\n  --bg-panel-2:#F5F5F7;\n  --bg-sunken:#E6E6EA;\n  --bg-row:#F3F3F6;\n  --bg-row-hi:#EBEBEF;\n  --bg-field:#F3F3F6;\n  --bg-float:#FFFFFF;    /* elevated */\n\n  /* ── alpha ladder of ink: 4 / 7 / 12 / 20 ── */\n  --ink-1:rgb(var(--ink-rgb) / .045);\n  --ink-2:rgb(var(--ink-rgb) / .08);\n  --ink-3:rgb(var(--ink-rgb) / .16);\n\n  --line:rgb(var(--ink-rgb) / .07);\n  --line-2:rgb(var(--ink-rgb) / .11);\n  --line-strong:rgb(var(--ink-rgb) / .2);\n  --section-line:rgb(var(--ink-rgb) / .09);\n\n  /* ── text: primary, then alpha steps of primary ── */\n  --tx:#1B1D23;\n  --tx-2:rgb(var(--ink-rgb) / .66);\n  --tx-3:rgb(var(--ink-rgb) / .48);\n  --tx-4:rgb(var(--ink-rgb) / .32);\n\n  --accent:#F0580A;\n  --accent-hover:#FF6A24;\n  --accent-dim:rgba(240,88,10,.12);\n  --accent-tx:#D84E06;\n  --on-accent:#FFFFFF;\n\n  --danger:#D93025;\n  --warning:#A15C00;\n  --success:#148F5E;\n\n  --blue:#2B6FE3;\n  --blue-deep:#2B4FD8;\n  --cream:#A89B76;\n  --sand:#8D8163;\n  --violet:#4C5BD8;\n  --gray:#6E6E76;\n  --green:var(--success);\n  --red:var(--danger);\n  --yellow:var(--warning);\n\n  /* ── radius: one base, multiplied ── */\n  --r-base:4px;\n  --r-xs:var(--r-base);\n  --r-sm:calc(var(--r-base) * 1.5);  /* 6  */\n  --r-md:calc(var(--r-base) * 2);    /* 8  */\n  --r-lg:calc(var(--r-base) * 3);    /* 12 */\n  --r-xl:calc(var(--r-base) * 4);    /* 16 */\n  --r-pill:999px;\n\n  --fw-regular:400; --fw-medium:500; --fw-semibold:600;\n\n  /* ── metrics ── */\n  --row-h:30px;\n  --hdr-h:38px;\n  --ctl-h:28px;   /* default control height: buttons, chips, fields inline */\n  --gut:10px;\n  --panel-edge-inset:10px; /* inset panel-top controls, search rows, and footer cards */\n  --pad:12px;     /* uniform outer padding for the whole shell */\n  --gap:10px;     /* uniform gap between docks/panels */\n  --hit:28px;     /* minimum interactive target */\n  --val-w:128px;  /* inspector value column: wells share one right-aligned track */\n\n  --f-ui:\"SF Pro Text\",-apple-system,BlinkMacSystemFont,\"Helvetica Neue\",sans-serif;\n  --f-mono:\"SF Mono\",ui-monospace,Menlo,monospace;\n\n  --fs-xs:11px; --fs-sm:12px; --fs-md:13px; --fs-lg:15px; --fs-xl:18px;\n  --lh:1.45;\n  --lh-tight:1.3;\n\n  /* ── flat control material; legacy token names remain extension-compatible ── */\n  --hairline:0.5px;\n  --ctl-edge:none;\n  --ctl-raised:var(--ink-1);\n  --ctl-edge-inset:\n    inset 0 var(--hairline) 0 rgb(var(--ink-rgb) / .06),\n    inset 0 0 0 var(--hairline) rgb(var(--ink-rgb) / .1);\n  --focus-ring:0 0 0 2px var(--bg-panel),0 0 0 4px color-mix(in srgb,var(--accent) 60%,transparent);\n\n  --shadow-raise:none;\n  /* panel: hairline ring + tight contact shadow + soft ambient, and a paper\n     highlight along the top edge so the card reads as a lifted sheet. */\n  --shadow-panel:\n    0 0 0 var(--hairline) rgb(var(--ink-rgb) / .09),\n    0 1px 1px rgb(var(--ink-rgb) / .04),\n    0 4px 10px -2px rgb(var(--ink-rgb) / .07),\n    inset 0 var(--hairline) 0 rgb(var(--paper-rgb) / .8);\n  --shadow-lift:0 4px 12px -2px rgb(var(--ink-rgb) / .1),0 0 0 var(--hairline) rgb(var(--ink-rgb) / .08);\n  --shadow-float:0 16px 40px -8px rgb(var(--ink-rgb) / .22),0 0 0 var(--hairline) rgb(var(--ink-rgb) / .1),inset 0 var(--hairline) 0 rgb(var(--paper-rgb) / .7);\n\n  /* ── motion: two durations, one curve ── */\n  --dur-1:75ms;    /* interaction: hover, press, selection */\n  --dur-2:100ms;   /* surface: menus, popovers, sheets */\n  --dur-3:160ms;   /* reveal: modals, large surfaces */\n  --ease:cubic-bezier(.22,1,.36,1);\n  --ease-io:cubic-bezier(.45,0,.2,1);\n\n  --disabled:.5;\n}\n:root[data-density=\"compact\"]{ --row-h:26px; --hdr-h:32px; --ctl-h:24px; --fs-md:12px; --gut:7px; --pad:9px; --gap:8px; }\n:root[data-density=\"comfy\"]{ --row-h:34px; --hdr-h:42px; --ctl-h:30px; --fs-md:14px; --gut:12px; --pad:14px; --gap:12px; }\n\n/* ── dark theme (alternate) ────────────────────────────── */\n:root[data-theme=\"dark\"]{\n  --ink-rgb:245 245 244;\n  --paper-rgb:255 255 255;\n\n  /* Tailwind Stone, kept close to 950 so the dark theme stays truly dark. */\n  --bg-window:#0C0A09;\n  --bg-rail:#100E0D;\n  --bg-panel:#1C1917;\n  --bg-panel-2:#151311;\n  --bg-sunken:#090807;\n  --bg-row:#211E1C;\n  --bg-row-hi:#292524;\n  --bg-field:#171412;\n  --bg-float:#292524;\n\n  --ink-1:rgb(var(--ink-rgb) / .05);\n  --ink-2:rgb(var(--ink-rgb) / .09);\n  --ink-3:rgb(var(--ink-rgb) / .18);\n\n  --line:rgb(var(--ink-rgb) / .07);\n  --line-2:rgb(var(--ink-rgb) / .11);\n  --line-strong:rgb(var(--ink-rgb) / .2);\n  --section-line:rgb(var(--ink-rgb) / .08);\n\n  --tx:#F5F5F4;\n  --tx-2:rgb(var(--ink-rgb) / .62);\n  --tx-3:rgb(var(--ink-rgb) / .44);\n  --tx-4:rgb(var(--ink-rgb) / .28);\n\n  --accent:#FF6B1A;\n  --accent-hover:#FF7B33;\n  --accent-dim:rgba(255,107,26,.15);\n  --accent-tx:#FF8B4D;\n\n  --danger:#F36357;\n  --warning:#F59E0B;\n  --success:#3FCF8E;\n\n  --blue:#4C8DFF;\n  --blue-deep:#3B62E8;\n  --cream:#E8E2CF;\n  --sand:#D8CFAF;\n  --violet:#6C7BE8;\n  --gray:#A9A9AE;\n\n  /* Controls use tonal fills in both themes, without lighting or elevation. */\n  --ctl-edge:none;\n  --ctl-raised:var(--ink-1);\n  --ctl-edge-inset:\n    inset 0 var(--hairline) 0 rgb(0 0 0 / .3),\n    inset 0 calc(var(--hairline) * -1) 0 rgb(var(--ink-rgb) / .08);\n  --focus-ring:0 0 0 2px var(--bg-panel),0 0 0 4px color-mix(in srgb,var(--accent) 65%,transparent);\n\n  --shadow-raise:none;\n  --shadow-panel:\n    0 0 0 var(--hairline) rgb(var(--ink-rgb) / .1),\n    0 1px 1px rgb(0 0 0 / .3),\n    0 6px 14px -4px rgb(0 0 0 / .45),\n    inset 0 var(--hairline) 0 rgb(var(--ink-rgb) / .07);\n  --shadow-lift:0 4px 14px -2px rgb(0 0 0 / .5),0 0 0 var(--hairline) rgb(var(--ink-rgb) / .09);\n  --shadow-float:0 20px 48px -8px rgb(0 0 0 / .65),0 0 0 var(--hairline) rgb(var(--ink-rgb) / .12),inset 0 var(--hairline) 0 rgb(var(--ink-rgb) / .1);\n}\n";
